<?php $pageTitle='Skills'; require 'config.php'; require 'includes/functions.php'; require_role('student');$uid=user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $sid=(int)($_POST['skill_id']??0);$lvl=max(1,min(5,(int)($_POST['level']??1)));$stmt=$pdo->prepare('INSERT INTO user_skills(user_id,skill_id,level,verified) VALUES(?,?,?,0) ON DUPLICATE KEY UPDATE level=VALUES(level)');$stmt->execute([$uid,$sid,$lvl]);flash('success','Skill added as unverified. Take an assessment to verify it.');header('Location: skills.php');exit;}
$all=$pdo->query('SELECT * FROM skills ORDER BY name')->fetchAll();$stmt=$pdo->prepare('SELECT us.*,s.name skill_name FROM user_skills us JOIN skills s ON s.id=us.skill_id WHERE user_id=? ORDER BY verified DESC,s.name');$stmt->execute([$uid]);$mine=$stmt->fetchAll();include 'includes/header.php';?>
<div class="grid two"><div class="card"><h2>Add Skill</h2><form method="post"><div class="form-group"><label>Skill</label><select name="skill_id"><?php foreach($all as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Declared Level (1–5)</label><select name="level"><?php for($i=1;$i<=5;$i++):?><option><?=$i?></option><?php endfor;?></select></div><button class="btn">Add Skill</button></form></div><div class="card"><h2>Level Guide</h2><p class="muted">1 Beginner • 2 Rookie • 3 Intermediate • 4 Advanced • 5 Professional</p><a class="btn secondary" href="assessments.php">Open Assessments</a></div></div><h2 class="section-title">Your Skills</h2><div class="grid"><?php foreach($mine as $s):?><div class="card"><span class="badge <?=$s['verified']?'':'warn'?>"><?=$s['verified']?'Verified':'Unverified'?></span><h3><?=e($s['skill_name'])?></h3><p>Level <?=e($s['level'])?> / 5</p></div><?php endforeach;?></div>
<?php include 'includes/footer.php'; ?>
